input.content:
/** A live cell's position on an unbounded grid, as `[x, y]`. */
export type Cell = [number, number];

const key = (x: number, y: number): string => `${x},${y}`;

const neighbors = (x: number, y: number): Cell[] => {
  const result: Cell[] = [];
  for (let dx = -1; dx <= 1; dx++) {
    for (let dy = -1; dy <= 1; dy++) {
      if (dx !== 0 || dy !== 0) result.push([x + dx, y + dy]);
    }
  }
  return result;
};

export function nextGeneration(cells: Cell[]): Cell[] {
  const living = new Set(cells.map(([x, y]) => key(x, y)));

  const liveNeighborCount = (x: number, y: number): number =>
    neighbors(x, y).filter(([nx, ny]) => living.has(key(nx, ny))).length;

  const candidates = new Map<string, Cell>();
  for (const [x, y] of cells) {
    candidates.set(key(x, y), [x, y]);
    for (const [nx, ny] of neighbors(x, y)) {
      candidates.set(key(nx, ny), [nx, ny]);
    }
  }

  const survivors: Cell[] = [];
  for (const [cellKey, [x, y]] of candidates) {
    const count = liveNeighborCount(x, y);
    const isAlive = living.has(cellKey);
    if (count === 3 || (isAlive && count === 2)) survivors.push([x, y]);
  }
  return survivors;
}

