const live = new Set<string>();
for (let x=0;x<3;x++) for (let y=0;y<3;y++) live.add(`${x},${y}`);
const count = (x:number,y:number) => {
  let c=0;
  for (let dx=-1;dx<=1;dx++) for (let dy=-1;dy<=1;dy++)
    if ((dx||dy) && live.has(`${x+dx},${y+dy}`)) c++;
  return c;
};
const out: Cell[] = [];
